#import <Foundation/Foundation.h>
#import "../storage/PVXHLSManifest.h"
static void Check(BOOL ok,NSString *message){if(!ok){fprintf(stderr,"FAIL %s\n",message.UTF8String);exit(1);}fprintf(stdout,"PASS %s\n",message.UTF8String);}
int main(void){@autoreleasepool{
 NSString *master=@"#EXTM3U\n#EXT-X-VERSION:7\n#EXT-X-MEDIA:TYPE=AUDIO,GROUP-ID=\"aud\",NAME=\"default\",DEFAULT=YES,AUTOSELECT=YES,URI=\"audio.m3u8\"\n#EXT-X-STREAM-INF:BANDWIDTH=800000,RESOLUTION=640x360,AUDIO=\"aud\"\nlow.m3u8\n#EXT-X-STREAM-INF:AVERAGE-BANDWIDTH=5000000,BANDWIDTH=6000000,RESOLUTION=1920x1080,CODECS=\"avc1.640028,mp4a.40.2\",AUDIO=\"aud\"\nhigh.m3u8\n";NSError *error=nil;PVXHLSManifest *m=[PVXHLSManifest parseText:master baseURL:[NSURL URLWithString:@"https://cdn.test/master.m3u8"] error:&error];Check(m.master&&m.variants.count==2,@"master variants");Check(m.bestVariant.width==1920&&m.bestVariant.height==1080,@"best variant by area");Check(m.defaultAudioForGroup(@"aud").isDefault,@"default audio");
 NSString *media=@"#EXTM3U\n#EXT-X-VERSION:7\n#EXT-X-TARGETDURATION:7\n#EXT-X-MEDIA-SEQUENCE:42\n#EXT-X-KEY:METHOD=AES-128,URI=\"key.bin\",IV=0x0000000000000000000000000000002a\n#EXT-X-MAP:URI=\"init.mp4\"\n#EXTINF:6.006,\nseg-42.ts\n#EXT-X-BYTERANGE:1024@2048\n#EXTINF:5.005,title\nseg-43.ts\n#EXT-X-ENDLIST\n";m=[PVXHLSManifest parseText:media baseURL:[NSURL URLWithString:@"https://cdn.test/high.m3u8"] error:&error];Check(!m.master&&m.endList&&m.segments.count==2,@"media segments");Check(fabs(m.segments[0].duration-6.006)<0.001&&m.segments[1].byterange.length>0,@"duration and byte range");Check(m.segments[0].key.URI.length&&m.segments[0].map.URI.length,@"key and map");NSString *local=[m localizedTextWithSegmentURLs:@{@"https://cdn.test/seg-42.ts":@"file:///tmp/42.ts",@"https://cdn.test/seg-43.ts":@"file:///tmp/43.ts",@"https://cdn.test/key.bin":@"file:///tmp/key.bin",@"https://cdn.test/init.mp4":@"file:///tmp/init.mp4"}];Check([local containsString:@"#EXTINF:6.006000"],@"preserve real duration");Check([local containsString:@"#EXT-X-MEDIA-SEQUENCE:42"],@"preserve media sequence");Check([local containsString:@"file:///tmp/42.ts"],@"localize segment URL");return 0;}}
